use super::{entity_details::{DeclaredGbpPeriodTotal, MemberDeclaration}, funder::{FunderId, FunderKind}, parliament_member::MemberId};

/// Minimal member identity in a ranking.
#[derive(Clone, Debug)]
pub struct RankedMember { pub id: MemberId, pub name: String }
/// Canonical funder identity and classification.
#[derive(Clone, Debug)]
pub struct RankedFunder { pub id: FunderId, pub name: String, pub kind: FunderKind }
/// Recipient's latest party identity.
#[derive(Clone, Debug)]
pub struct RankedParty { pub id: i32, pub name: String }
/// A ranked identity and its backend-owned financial total.
#[derive(Debug)]
pub struct Ranking<I> { pub identity: I, pub total: DeclaredGbpPeriodTotal }
/// Four top-ten boards from one current-term snapshot.
#[derive(Debug)]
pub struct Rankings {
    pub current_term_start: chrono::DateTime<chrono::Utc>,
    pub members: Vec<Ranking<RankedMember>>,
    pub individuals: Vec<Ranking<RankedFunder>>,
    pub companies: Vec<Ranking<RankedFunder>>,
    pub parties: Vec<Ranking<RankedParty>>,
}
/// One declaration with canonical funder identities for its funding entries.
pub struct RankingDeclaration {
    pub member: RankedMember,
    pub party: RankedParty,
    pub declaration: MemberDeclaration,
    pub funders: Vec<Option<RankedFunder>>,
}
