//! Exact current-term rankings use the same aggregate as member summaries.
use crate::domain::{models::{declared_totals::{CurrentParliamentStart, PeriodAggregate}, entity_details::DeclarationCategory, funder::FunderKind, rankings::*}, repositories::rankings::{RankingsError, RankingsRepo}};
use std::collections::BTreeMap;
/// Fixed current-term top-ten operation.
pub trait RankingsService: Clone + Send + Sync + 'static {
    /// Returns all four boards from one snapshot.
    fn rankings(&self) -> impl Future<Output = Result<Rankings, RankingsError>> + Send;
}
/// Rankings application service.
#[derive(Clone)]
pub struct Service<R> { repo: R }
impl<R> Service<R> {
    /// Creates a rankings service.
    pub const fn new(repo: R) -> Self { Self { repo } }
}
fn top<K: Ord, I>(groups: BTreeMap<K, (I, PeriodAggregate)>) -> Vec<Ranking<I>> {
    let mut rows: Vec<_> = groups.into_iter().map(|(key, (identity, aggregate))| (key, Ranking { identity, total: aggregate.gbp_total() })).collect();
    rows.sort_by(|left, right| right.1.total.amount.cmp(&left.1.total.amount).then_with(|| left.0.cmp(&right.0)));
    rows.into_iter().take(10).map(|(_, row)| row).collect()
}
impl<R: RankingsRepo> RankingsService for Service<R> {
    async fn rankings(&self) -> Result<Rankings, RankingsError> {
        let boundary = CurrentParliamentStart::new();
        let sources = self.repo.ranking_declarations(boundary.value()).await?;
        Ok(summarize(sources, boundary))
    }
}
fn summarize(sources: Vec<RankingDeclaration>, boundary: CurrentParliamentStart) -> Rankings {
    let mut members = BTreeMap::new();
    let mut individuals = BTreeMap::new();
    let mut companies = BTreeMap::new();
    let mut parties = BTreeMap::new();
    for source in sources {
        let declaration = source.declaration;
        if !boundary.includes(&declaration) { continue; }
        members.entry(source.member.id.value()).or_insert_with(|| (source.member, PeriodAggregate::default())).1.observe(&declaration);
        if declaration.category != DeclarationCategory::DonationSupport { continue; }
        let party = parties.entry(source.party.id).or_insert_with(|| (source.party.clone(), PeriodAggregate::default()));
        // Stored party labels may differ; identity remains the party ID.
        if source.party.name < party.0.name { party.0.name = source.party.name; }
        party.1.observe(&declaration);
        let mut funders = BTreeMap::new();
        for (entry, funder) in declaration.entries.iter().zip(source.funders) {
            if let Some(funder) = funder {
                funders.entry(funder.id.value()).or_insert_with(|| (funder, Vec::new())).1.push(entry.clone());
            }
        }
        for (key, (funder, entries)) in funders {
            let board = match funder.kind {
                FunderKind::Individual => &mut individuals,
                FunderKind::Company => &mut companies,
                FunderKind::Trust | FunderKind::TradeUnion | FunderKind::Other | FunderKind::NotSpecified | FunderKind::BuildingSociety | FunderKind::LimitedLiabilityPartnership | FunderKind::UnincorporatedAssociation | FunderKind::FriendlySociety | FunderKind::RegisteredParty => continue,
            };
            let mut projected = declaration.clone();
            projected.entries = entries;
            board.entry(key).or_insert_with(|| (funder, PeriodAggregate::default())).1.observe(&projected);
        }
    }
    Rankings { current_term_start: boundary.value(), members: top(members), individuals: top(individuals), companies: top(companies), parties: top(parties) }
}
