import { formatPounds } from "./member-summary";
import type { DeclaredGbpPeriodTotal } from "./entity-details";
import type { CategoryWheelOption, RankingRow } from "./ui";

export type RankingCategory = "members" | "individuals" | "companies" | "parties";
export interface RankingEntry {
  id: string;
  name: string;
  context: string | null;
  total: DeclaredGbpPeriodTotal;
}
export interface Rankings {
  currentTermStart: string;
  members: RankingEntry[];
  individuals: RankingEntry[];
  companies: RankingEntry[];
  parties: RankingEntry[];
}
// Geometry belongs to the feature; the shared selector renders supplied sectors.
export const rankingCategories = [
  { id: "members", label: "MPs", icon: "parliament", accent: "member", path: "M138 8 A130 130 0 0 0 8 138 L78 138 A60 60 0 0 1 138 78 Z", x: 73, y: 73 },
  { id: "individuals", label: "Individuals", icon: "person", accent: "funder", path: "M146 8 A130 130 0 0 1 276 138 L206 138 A60 60 0 0 0 146 78 Z", x: 211, y: 73 },
  { id: "companies", label: "Companies", icon: "building", accent: "funder", path: "M8 146 A130 130 0 0 0 138 276 L138 206 A60 60 0 0 1 78 146 Z", x: 73, y: 211 },
  { id: "parties", label: "Parties", icon: "group", accent: "neutral", path: "M146 276 A130 130 0 0 0 276 146 L206 146 A60 60 0 0 1 146 206 Z", x: 211, y: 211 },
] satisfies CategoryWheelOption<RankingCategory>[];

function magnitude(value: string, scale: number): bigint {
  const [whole, fraction = ""] = value.replace(/^-/, "").split(".");
  return BigInt(whole + fraction.padEnd(scale, "0"));
}
export function rankingRows(rankings: Rankings, category: RankingCategory): RankingRow[] {
  const entries = rankings[category];
  const scale = Math.max(0, ...entries.map(({ total }) => total.amount?.split(".")[1]?.length ?? 0));
  const values = entries.map(({ total }) => magnitude(total.amount ?? "0", scale));
  const maximum = values.reduce((left, right) => left > right ? left : right, 0n);
  return entries.map((entry, index) => ({
    key: `${category}:${entry.id}`,
    name: entry.name,
    context: entry.context ?? `${entry.total.declarationCount} declaration${entry.total.declarationCount === 1 ? "" : "s"}`,
    href: category === "parties" ? undefined : `/${category === "members" ? "members" : "funders"}/${entry.id}`,
    amount: formatPounds(entry.total.amount),
    incomplete: entry.total.incomplete,
    width: maximum === 0n ? 0 : Number(values[index] * 10000n / maximum) / 100,
    negative: entry.total.amount?.startsWith("-") ?? false,
    accent: category === "members" ? "member" : category === "parties" ? "neutral" : "funder",
  }));
}
