//! Current-term rankings retain exact totals and distinct entity identities.
use super::{entity_details::{DeclaredGbpPeriodTotal, MemberDeclaration}, funder::{FunderId, FunderKind}, parliament_member::MemberId};

/// Minimal member identity in a ranking.
#[derive(Clone, Debug)]
pub struct RankedMember {
